from taf.ul.ettf.logger import custom_logger, log
from taf.ul.ettf.config.globals import SIM_GNB_IP, SIM_VM_IF_NAME, SIM_VM_INTERFACE
from taf.ul.ettf.object_provider.provider import provider
from taf.ul.ettf.utils.robot_handlers import with_callback_name
from ta5g_egate import ta5g_egate
from ta5g_testline_management import ta5g_testline_management
import os
import shutil
import psutil


logger = custom_logger('Setups_Simulator')
REACH_ONAIR_TIMEOUT = 180


def is_egate_opened():
    return [p for p in psutil.process_iter() if 'egate' in str(p.name)]


def disabled(*args, **kwargs):
    pass


class SimulatedEnb(object):
    def __init__(self):
        self.vm_management = ta5g_testline_management()

    @log('Starting simulated Enb...', 'Simulated Enb is set up', logger)
    def start(self):
        self.vm_management.start_default_simulated_enb_interface()

    @with_callback_name('Simulated Enb Teardown')
    def simulated_enb_teardown(self):
        self.vm_management.stop_default_simulated_enb_interface()


class SimulatedGnb(object):
    def __init__(self, ip=None):
        self.vm_management = ta5g_testline_management()
        self.ip = ip if ip else SIM_GNB_IP

    @log('Starting simulated Gnb...', 'Simulated Gnb is set up', logger)
    def start(self):
        self.vm_management.start_default_simulated_gnb_interface(self.ip)

    @with_callback_name('Simulated Gnb Teardown')
    def simulated_gnb_teardown(self):
        self.vm_management.stop_default_simulated_gnb_interface(self.ip)


class SimulatedNetworkInterface(object):
    def __init__(self, ip=None, name=None):
        self.vm_management = ta5g_testline_management()
        self.ip = ip if ip else SIM_VM_INTERFACE
        self.name = name if name else SIM_VM_IF_NAME

    @log('Starting simulated virtual interface...', 'Simulated virtual interface is set up', logger)
    def start(self):
        self.vm_management.start_vm_ethernet_interface(self.name, self.ip)

    @with_callback_name('Simulated Interface Teardown')
    def simulated_interface_teardown(self):
        self.vm_management.stop_vm_ethernet_interface(self.name, self.ip)


class Egate(object):
    LOG_FILEPATH = '/opt/iphy/latest/egate_console.log'
    LOG_NAME = 'egate_console.log'

    def __init__(self, config_filepath, logs_directory):
        self.config = config_filepath
        self.logs_directory = logs_directory
        self.egate = ta5g_egate()

    @log('Waiting for On-Air state...', 'On-Air state reached', logger)
    def reach_onair(self, remote_hosts, timeout=REACH_ONAIR_TIMEOUT):
        self.egate.reach_onair(lua_cfg=self.config, logs_dirpath=self.logs_directory, timeout=timeout, remote_hosts=remote_hosts)

    @with_callback_name('Egate teardown')
    def teardown(self):
        self.egate.teardown_egate_and_collect_logs(logs_dirpath=self.logs_directory)
        self._collect_internal_logs()

    def keep_alive(self):
        provider.get_egate().save_egate = True
        provider.get_egate().stop_and_collect_wts_logs = disabled

    def _collect_internal_logs(self):
        shutil.copyfile(src=self.LOG_FILEPATH, dst=os.path.join(self.logs_directory, self.LOG_NAME))


class AliveEgate(object):
    def __init__(self):
        self.egate = provider.get_egate()

    @log('Connecting to already configured Egate session...', 'Connected', logger)
    def reach_onair(self, remote_hosts, timeout=REACH_ONAIR_TIMEOUT):
        self.egate.stop_and_collect_wts_logs = disabled
        self.egate.setup_egate(egate_port=20000, alias='default', save_egate=True)

    def teardown(self):
        pass
